fn trunc_len(n: usize, m: usize) -> usize {
    if m == 0 {
        n
    } else if m >= n {
        1
    } else {
        n - m
    }
}

fn legder(c: Vec<f64>, m: u8, _scl: f64) -> Vec<f64> {
    let n = c.len();
    let m_usize = m as usize;
    let out_len = trunc_len(n, m_usize);
    if out_len == n {
        // m == 0 case: return array unchanged
        c
    } else {
        // Either m >= n or 0 < m < n cases
        // Slice length == out_len, must ensure length>=1
        c.into_iter().take(out_len).collect()
    }
}